```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <set>
using namespace std;

bool isPalindrome(const string& s) {
    int left = 0, right = s.length() - 1;
    while (left < right) {
        if (s[left] != s[right]) return false;
        left++;
        right--;
    }
    return true;
}

int main() {
    ifstream plik("napisy.txt");
    string s;
    int lacznie = 0;
    while (plik >> s) {
        vector<string> palindromy;
        set<string> widziane;
        int n = s.length();
        for (int i = 0; i < n; i++) {
            for (int len = 3; len <= n - i; len++) {
                string pod = s.substr(i, len);
                if (widziane.find(pod) == widziane.end() && isPalindrome(pod)) {
                    palindromy.push_back(pod);
                    widziane.insert(pod);
                }
            }
        }
        cout << s << ": ";
        if (palindromy.empty()) {
            cout << "(brak)" << endl;
        } else {
            for (int i = 0; i < (int)palindromy.size(); i++) {
                if (i > 0) cout << " ";
                cout << palindromy[i];
            }
            cout << endl;
        }
        lacznie += palindromy.size();
    }
    cout << "Lacznie unikalnych: " << lacznie << endl;
    return 0;
}
```

**Wyjasnienie**: Generujemy wszystkie podnapisy dlugosci >= 3, sprawdzamy palindromicznosc i zachowujemy unikalne w kolejnosci pierwszego wystapienia. Set eliminuje duplikaty, a wektor zachowuje kolejnosc.

Weryfikacja:
- abacaba: palindromy: aba(0-2), abacaba(0-6), bacab(1-5), aca(2-4). Uwaga: aba(4-6) to duplikat -> 4 unikalne
- racecar: racecar(0-6), aceca(1-5), cec(2-4) -> 3 unikalne
- abc: brak palindromow dlugosci >= 3 -> (brak)
- level: level(0-4), eve(1-3) -> 2 unikalne
- abba: abba(0-3) -> 1 unikalny
- madam: madam(0-4), ada(1-3) -> 2 unikalne
Lacznie: 4+3+0+2+1+2 = 12
